// A PHP list with gaps (as array_diff gives) is dumped as an object: its groups
// and tags are read in key order.
func TestPhpdocSeparationGroupsWithGaps(t *testing.T) {
	t.Parallel()
	listed := PhpdocSeparation{}.WithConfig(map[string]any{"groups": []any{[]any{"param", "return"}, []any{"throws"}}}).(fixerRule)
	gapped := PhpdocSeparation{}.WithConfig(map[string]any{"groups": map[string]any{
		"10": []any{"throws"},
		"2":  map[string]any{"3": "return", "1": "param"},
	}}).(fixerRule)
	src := "<?php\n/**\n * @param int $a\n *\n * @return int\n * @throws E\n * @custom\n */\nfunction f() {}\n"
	want, _ := apply(t, listed, src)
	if got, _ := apply(t, gapped, src); got != want {
		t.Errorf("got=%q want=%q", got, want)
	}
}
